package main

const indexHTML = `<!doctype html><html lang="ja"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>QnapAssistant</title><style>body{font-family:system-ui;margin:0;background:#101217;color:#eee}.wrap{max-width:1180px;margin:auto;padding:20px}.card{background:#191d25;border:1px solid #303745;border-radius:14px;padding:16px;margin:12px 0}input,select,button{background:#0f1218;color:#eee;border:1px solid #3b4454;border-radius:8px;padding:9px}input,select{width:100%;box-sizing:border-box}button{cursor:pointer;margin:3px}.grid{display:grid;grid-template-columns:repeat(auto-fit,minmax(180px,1fr));gap:10px}.ok{color:#65d98b}.off{color:#e6bd5a}pre{white-space:pre-wrap;max-height:380px;overflow:auto;background:#0c0e12;padding:12px;border-radius:8px}label{font-size:12px;color:#aeb7c6}.hint{font-size:12px;color:#8f9bad;margin:8px 0}.profile{border:1px solid #303745;border-radius:10px;padding:12px}</style></head><body><div class="wrap"><h1>QnapAssistant</h1><div class="card"><b>LLM:</b> <span id="status">...</span> <button onclick="act('start')">Load LLM</button><button onclick="act('stop')">Unload LLM</button><button onclick="act('restart')">Restart LLM</button></div><div class="card"><b>Voice:</b> <span id="voiceStatus">...</span> <button onclick="voiceAct('start')">Load Voice</button><button onclick="voiceAct('stop')">Unload Voice</button><button onclick="voiceAct('restart')">Restart Voice</button><div class="hint">SenseVoice + Piper/Tsukuyomi stay resident. Supertonic is lazy fallback.</div></div><div class="card"><h3>Voice client profiles</h3><div class="grid"><div><label>Default profile</label><select id="VOICE_PROFILE_DEFAULT"><option value="generic">Generic / current compatibility</option><option value="m5go">M5GO / constrained device</option></select></div></div><div class="hint">Requests can override with ?profile=m5go or X-Qnap-Voice-Profile: m5go. Generic preserves current behavior; M5GO defaults to 16 kHz, binary multipart streaming, emoji filtering and conservative peak limiting.</div><div class="grid"><div class="profile"><b>Generic</b><div class="grid"><div><label>Sample rate (0=native)</label><input id="VOICE_GENERIC_SAMPLE_RATE"></div><div><label>Peak target (0=off)</label><input id="VOICE_GENERIC_PEAK_TARGET"></div><div><label>Strip emoji</label><select id="VOICE_GENERIC_STRIP_EMOJI"><option value="0">No</option><option value="1">Yes</option></select></div><div><label>Stream format</label><select id="VOICE_GENERIC_STREAM_FORMAT"><option value="ndjson">NDJSON + base64</option><option value="multipart">Multipart binary</option></select></div><div><label>Chunk min chars</label><input id="VOICE_GENERIC_CHUNK_MIN_CHARS"></div><div><label>Chunk max chars</label><input id="VOICE_GENERIC_CHUNK_MAX_CHARS"></div></div></div><div class="profile"><b>M5GO</b><div class="grid"><div><label>Sample rate</label><input id="VOICE_M5_SAMPLE_RATE"></div><div><label>Peak target</label><input id="VOICE_M5_PEAK_TARGET"></div><div><label>Strip emoji</label><select id="VOICE_M5_STRIP_EMOJI"><option value="0">No</option><option value="1">Yes</option></select></div><div><label>Stream format</label><select id="VOICE_M5_STREAM_FORMAT"><option value="multipart">Multipart binary</option><option value="ndjson">NDJSON + base64</option></select></div><div><label>Chunk min chars</label><input id="VOICE_M5_CHUNK_MIN_CHARS"></div><div><label>Chunk max chars</label><input id="VOICE_M5_CHUNK_MAX_CHARS"></div></div></div></div><button onclick="saveVoiceProfiles()">Save voice profiles</button></div><div class="card"><h3>Models</h3><select id="models"></select><button onclick="selectModel()">Select</button><div class="grid"><div><label>Download URL</label><input id="dlurl"></div><div><label>Filename (.gguf)</label><input id="dlname"></div></div><button onclick="downloadModel()">Download to Public</button><div id="dlstate"></div></div><div class="card"><h3>LLM settings</h3><div class="grid"><div><label>Qwen3 Thinking</label><select id="thinking"><option value="off">OFF - fast</option><option value="on">ON - think</option><option value="passthrough">Client / model default</option></select></div></div><button onclick="setThinking()">Apply Thinking Mode</button><div id="form" class="grid"></div><label>EXTRA_ARGS</label><input id="EXTRA_ARGS"><button onclick="saveCfg()">Save LLM settings</button></div><div class="card"><h3>Logs</h3><button onclick="logs('llama')">llama-server</button><button onclick="logs('admin')">manager</button><pre id="logs"></pre></div></div><script>
const keys=['THREADS','THREADS_BATCH','CONTEXT','BATCH','UBATCH','PARALLEL','IDLE_TIMEOUT_SECONDS','ADMIN_PORT','BACKEND_PORT'];
const voiceKeys=['VOICE_PROFILE_DEFAULT','VOICE_GENERIC_SAMPLE_RATE','VOICE_GENERIC_PEAK_TARGET','VOICE_GENERIC_STRIP_EMOJI','VOICE_GENERIC_STREAM_FORMAT','VOICE_GENERIC_CHUNK_MIN_CHARS','VOICE_GENERIC_CHUNK_MAX_CHARS','VOICE_M5_SAMPLE_RATE','VOICE_M5_PEAK_TARGET','VOICE_M5_STRIP_EMOJI','VOICE_M5_STREAM_FORMAT','VOICE_M5_CHUNK_MIN_CHARS','VOICE_M5_CHUNK_MAX_CHARS'];
async function j(u,o){let r=await fetch(u,o);if(!r.ok)throw new Error(await r.text());return r.json()}
async function refresh(){let s=await j('/api/status');status.textContent=(s.llm_loaded?'loaded / resident':'unloaded')+' | RAM free '+Math.round((s.memory_available_bytes||0)/1048576)+' MB | load '+(s.load1||'-');status.className=s.llm_loaded?'ok':'off';dlstate.textContent=s.download.active?('Downloading '+s.download.name+': '+Math.round((s.download.written_bytes||0)/1048576)+' MB'):(s.download.error||'');let v=await j('/api/voice/status');if(v.worker_running){voiceStatus.textContent='loaded / resident | ASR '+(v.asr_loaded?'hot':'cold')+' | Supertonic '+(v.tts_loaded?'hot':'lazy')+' | Piper '+(v.piper_resident?'resident':'not resident');voiceStatus.className='ok'}else{voiceStatus.textContent='unloaded';voiceStatus.className='off'}let c=await j('/api/config');for(let k of keys.concat(voiceKeys)){let e=document.getElementById(k);if(e)e.value=c[k]||''}EXTRA_ARGS.value=c.EXTRA_ARGS||'';let th=await j('/api/thinking');thinking.value=th.mode||'off';let ms=await j('/api/models');models.innerHTML=ms.map(m=>'<option value="'+m.path+'" '+(m.selected?'selected':'')+'>'+m.name+' ('+(m.size/1048576).toFixed(0)+' MB)</option>').join('')}
async function act(x){await j('/api/llm/'+x,{method:'POST'});refresh()}
async function voiceAct(x){await j('/api/voice/'+x,{method:'POST'});refresh()}
async function setThinking(){await j('/api/thinking',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify({mode:thinking.value})});refresh()}
async function saveCfg(){let c={};for(let k of keys)c[k]=document.getElementById(k).value;c.EXTRA_ARGS=EXTRA_ARGS.value;await j('/api/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(c)});refresh()}
async function saveVoiceProfiles(){let c={};for(let k of voiceKeys)c[k]=document.getElementById(k).value;await j('/api/config',{method:'PUT',headers:{'Content-Type':'application/json'},body:JSON.stringify(c)});refresh()}
async function selectModel(){await j('/api/models/select',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({path:models.value})});refresh()}
async function downloadModel(){await j('/api/models/download',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({URL:dlurl.value,Filename:dlname.value})});refresh()}
async function logs(t){let r=await fetch('/api/logs?target='+t+'&lines=400');document.getElementById('logs').textContent=await r.text()}
form.innerHTML=keys.map(k=>'<div><label>'+k+'</label><input id="'+k+'"></div>').join('');refresh();setInterval(refresh,5000);
</script></body></html>`
